from h import *
R=[]
R.append((6938246,{
"es":L("Hongos portobello rellenos de pavo con ensalada de espinacas, queso feta y nueces pecanas",
"Disfrute de los sabores intensos de la temporada con nuestros hongos rellenos aptos para personas con diabetes, acompañados de una ensalada refrescante. Este plato del Patrón de Comidas Muy Bajo en Carbohidratos es delicioso y rico en nutrientes, lo que lo convierte en una excelente opción para una comida saludable.",
"4","1 hongo relleno, 2 tazas de ensalada",
["4 hongos portobello grandes (solo los sombreros)","1 libra de pavo molido magro (99 % magro)","1 cebolla pequeña (finamente picada)","2 dientes de ajo (picados)","7 1/2 onzas de tomates en cubitos (sin sal añadida; escurridos si son enlatados)","1/2 cucharadita de orégano seco","1/2 cucharadita de pimentón ahumado","1/4 cucharadita de pimienta negra","1 entero de aceite de oliva en aerosol","5 onzas de espinacas tiernas","1/4 taza de queso feta reducido en grasa (desmenuzado)","1/4 taza de nueces pecanas (picadas)","1/2 pepino inglés entero (en rodajas finas)","1 taza de tomates cherry (partidos por la mitad)","2 cucharadas de vinagre balsámico","1 cucharada de aceite de oliva","1 cucharadita de mostaza Dijon"],
["Precaliente el horno a 375 grados F. Forre una bandeja para hornear con papel pergamino.","Quite los tallos y raspe las laminillas de los sombreros de los hongos portobello. Rocíe ligeramente los sombreros con aceite de oliva y colóquelos en la bandeja con la parte abierta hacia arriba.","Caliente un sartén antiadherente a fuego medio. Agregue el pavo molido y la cebolla picada. Cocine, desmenuzando el pavo, hasta que ya no esté rosado (unos 5–6 minutos). Agregue el ajo picado y cocine 1 minuto más.","Incorpore los tomates en cubitos, el orégano, el pimentón ahumado, la sal y la pimienta. Mezcle bien y cocine otros 3–4 minutos.","Divida la mezcla de pavo en partes iguales entre los sombreros de los hongos. Hornee de 15 a 20 minutos, o hasta que los hongos estén tiernos y el relleno esté caliente por dentro.","En un tazón grande, combine las espinacas tiernas, el queso feta desmenuzado, las nueces pecanas tostadas, el pepino y los tomates cherry.","En un tazón pequeño, bata el vinagre balsámico, el aceite de oliva y la mostaza Dijon. Rocíe el aderezo sobre la ensalada y mezcle para cubrir de manera uniforme.","Sirva un hongo relleno con la ensalada a un lado."]),
"ar":L("فطر البورتوبيلو المحشو بالديك الرومي مع سلطة السبانخ والجبن الفيتا والبيكان",
"استمتع بالنكهات الغنية للموسم مع الفطر المحشو المناسب لمرضى السكري، يُقدَّم مع سلطة منعشة. هذا الطبق من نمط الوجبات شديد الانخفاض في الكربوهيدرات لذيذ وغني بالعناصر الغذائية، مما يجعله خيارًا مثاليًا لوجبة صحية.",
"4","1 فطرة محشوة، 2 كوب سلطة",
["4 فطر بورتوبيلو كبير (القبعات فقط)","1 رطل ديك رومي مفروم قليل الدهن (99% خالٍ من الدهون)","1 بصلة صغيرة (مقطعة إلى مكعبات صغيرة جدًا)","2 فص ثوم (مفروم)","7½ أونصة طماطم مقطعة إلى مكعبات (بدون ملح مضاف، ومصفاة إن كانت معلبة)","½ ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة بابريكا مدخنة","¼ ملعقة صغيرة فلفل أسود","1 بخة زيت زيتون بخاخ","5 أونصة سبانخ صغيرة الأوراق","¼ كوب جبن فيتا قليل الدسم (مفتت)","¼ كوب بيكان (مفروم)","½ خيارة إنجليزية (مقطعة شرائح رفيعة)","1 كوب طماطم كرزية (مقطعة إلى نصفين)","2 ملعقة كبيرة خل بلسمي","1 ملعقة كبيرة زيت زيتون","1 ملعقة صغيرة خردل ديجون"],
["سخّن الفرن مسبقًا على 375 درجة فهرنهايت (190 درجة مئوية). بطّن صينية الخبز بورق زبدة.","انزع السيقان واكشط الشرائح الداخلية من قبعات فطر البورتوبيلو. رشّ القبعات برفق بزيت الزيتون وضعها على الصينية والجهة المفتوحة إلى الأعلى.","سخّن مقلاة غير لاصقة على نار متوسطة. أضف الديك الرومي المفروم والبصل المقطع. اطهِ مع تفتيت الديك الرومي حتى يزول اللون الوردي (نحو 5–6 دقائق). أضف الثوم المفروم واطهِ دقيقة واحدة إضافية.","أضف الطماطم المقطعة والأوريجانو والبابريكا المدخنة والملح والفلفل وقلّب. اخلط جيدًا واطهِ 3–4 دقائق أخرى.","وزّع خليط الديك الرومي بالتساوي على قبعات الفطر. اخبز من 15 إلى 20 دقيقة، أو حتى يلين الفطر وتسخن الحشوة جيدًا.","في وعاء كبير، اخلط السبانخ الصغيرة والجبن الفيتا المفتت والبيكان المحمص والخيار والطماطم الكرزية.","في وعاء صغير، اخفق الخل البلسمي وزيت الزيتون وخردل ديجون. اسكب الصلصة فوق السلطة وقلّب حتى تتغطى بالتساوي.","قدّم فطرة محشوة واحدة مع السلطة بجانبها."])}))
R.append((6938670,{
"ar":L("ستروغانوف الديك الرومي",
"لا داعي لأكل ديك رومي كامل في يوم عيد الشكر! احتفظ ببعض بقايا الطعام لاستخدامها في وصفات أخرى مثل هذه. احصل على وجبات جديدة مع مراقبة حصصك كجزء من إدارة مرض السكري!",
"6","3 أونصة ديك رومي + ⅔ كوب من خليط الفطر والمعكرونة",
["6 أونصة معكرونة بالبيض","2 ملعقة صغيرة بذور الخشخاش","18 أونصة صدر ديك رومي (مشوي طازج، مقطع إلى شرائح بحجم 2 × ½ بوصة)","⅛ ملعقة صغيرة ملح كوشر","½ ملعقة صغيرة فلفل أسود مطحون طازجًا","2 حبة فطر بورتوبيلو (4 أونصات لكل واحدة)","1 بصلة صفراء صغيرة (مقطعة شرائح رفيعة)","1 ملعقة كبيرة زبدة","1½ ملعقة كبيرة دقيق متعدد الاستخدامات","1½ كوب مرق لحم بقري (قليل الصوديوم)","½ كوب زبادي يوناني سادة خالٍ من الدسم","1½ ملعقة صغيرة خردل ديجون"],
["اطهِ المعكرونة حسب إرشادات العبوة. قلّب المعكرونة مع بذور الخشخاش وأعدها إلى قدر الطهي الفارغ لتبقى دافئة. رش شرائح الديك الرومي بالملح والفلفل وقلّبها لتتغطى. انزع سيقان الفطر وتخلّص منها. قطّع قبعات الفطر إلى أرباع ثم إلى شرائح رفيعة.","في أثناء ذلك، رشّ مقلاة كبيرة غير لاصقة برفق ببخاخ الطهي غير اللاصق وضعها على نار متوسطة إلى عالية. قلّب البصل في المقلاة لمدة دقيقتين. أضف الفطر وقلّبه حتى يلين، نحو 5-6 دقائق. انقله إلى وعاء كبير.","ذوّب الزبدة في المقلاة على نار متوسطة. أضف الدقيق واطهِ لمدة دقيقة واحدة مع التحريك المستمر. أضف المرق تدريجيًا مع الخفق. اطهِ مع التحريك بملعقة خشبية حتى تتكاثف الصلصة وتغلي، نحو 4 دقائق.","خفّض النار إلى هادئة. اخفق الزبادي اليوناني والخردل. أعد الديك الرومي والخضار المحفوظة مع عصارتها المتجمعة إلى المقلاة. اطهِ حتى تسخن جيدًا (دون أن تغلي). وزّع المعكرونة على الأطباق واسكب الستروغانوف فوقها بالملعقة."])}))
R.append((6942512,{
"ar":L("لقيمات البروكلي والجبن",
"هذه اللقيمات وجبة خفيفة أو مقبلات رائعة، وطريقة ممتازة لإضافة المزيد من الخضار إلى خطتك الغذائية الصحية.",
"6","5 قطع",
["1 بخة، 0.25 غرام بخاخ طهي غير لاصق","2 رأس بروكلي (مقلّم)","1 بيضة كبيرة","1 بياض بيضة كبيرة","⅓ كوب جبن شيدر أو جبن على الطريقة المكسيكية مبشور قليل الدسم","⅓ كوب فتات الخبز","½ كوب بصل (مفروم)","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية). رشّ صينية خبز كبيرة (أو صينيتين صغيرتين) ببخاخ الطهي. ضعها جانبًا.","اطهِ البروكلي على البخار نحو 10 إلى 12 دقيقة حتى يلين. ضعه جانبًا ليبرد (نحو 10 دقائق).","ضع البروكلي وبقية المكونات في الخلاط أو محضّر الطعام وشغّله على دفعات قصيرة للمزج. لا تفرط في الخلط؛ يجب أن يكون الخليط خشنًا قليلًا وليس عجينة ناعمة. اترك الخليط ليرتاح 10 دقائق.","بعد أن يرتاح الخليط، قلّبه، ثم خذ منه بملعقة كبيرة وضع الكتل على صينية الخبز المجهزة.","رشّ أعلى كل كرة برفق ببخاخ الطهي. اخبز 15 دقيقة. اقلب القطع واخبز 10 دقائق إضافية، أو حتى يصبح لونها ذهبيًا."])}))
R.append((6942698,{
"es":L("Ensalada de espinacas y naranja",
"Esta ensalada fresca tendrá un sabor perfecto en cualquier época del año, pero puede ser especialmente bienvenida en otoño o invierno, cuando los cítricos son más abundantes y hay menos variedad de otros productos frescos.",
"2","1 taza de ensalada con 2 cucharadas de aderezo",
["1 taza de espinacas tiernas","2 cucharadas de apio (en rodajas)","2 champiñones blancos pequeños (en rodajas)","1 cebolla morada mediana (partida por la mitad y separada en aros)","1/2 naranja mediana (pelada y separada en gajos)","2 cucharadas de jugo de naranja","1 cucharada de jugo de limón","1 cucharadita de aceite de oliva","1 cucharadita de salsa de soya baja en sodio","1 cucharadita de miel","1/8 cucharadita de jengibre molido","1/8 cucharadita de pimienta negra","1 cucharada de pepitas (semillas de calabaza)"],
["En un tazón mediano para ensalada, mezcle las espinacas, el apio, los champiñones, la cebolla y los gajos de naranja.","En un tazón pequeño, bata los demás ingredientes, excepto las semillas de calabaza. Rocíe sobre la ensalada. Mezcle para combinar. Decore con las semillas de calabaza."]),
"ar":L("سلطة السبانخ والبرتقال",
"ستكون هذه السلطة المنعشة لذيذة في أي وقت من السنة، لكنها قد تكون مرحبًا بها بشكل خاص في الخريف أو الشتاء، حين تتوافر الحمضيات بكثرة وتقل أنواع الخضار والفاكهة الأخرى.",
"2","1 كوب سلطة مع 2 ملعقة كبيرة صلصة",
["1 كوب سبانخ صغيرة الأوراق","2 ملعقة كبيرة كرفس (مقطع شرائح)","2 حبة فطر أبيض (شامبينيون) صغيرة (مقطعة شرائح)","1 بصلة حمراء متوسطة (مقسومة إلى نصفين ومفصولة إلى حلقات)","½ برتقالة متوسطة (مقشرة ومقسمة إلى فصوص)","2 ملعقة كبيرة عصير برتقال","1 ملعقة كبيرة عصير ليمون","1 ملعقة صغيرة زيت زيتون","1 ملعقة صغيرة صلصة صويا قليلة الصوديوم","1 ملعقة صغيرة عسل","⅛ ملعقة صغيرة زنجبيل مطحون","⅛ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة بذور اليقطين (بيبيتاس)"],
["في وعاء سلطة متوسط، اخلط السبانخ والكرفس والفطر والبصل وفصوص البرتقال.","في وعاء صغير، اخفق بقية المكونات باستثناء بذور اليقطين. اسكبها فوق السلطة وقلّب للمزج. زيّنها ببذور اليقطين."])}))
R.append((6942750,{
"es":L("Pavo bajo en sodio","Información nutricional del pavo bajo en sodio","1","3 onzas",["3 onzas de pavo bajo en sodio"],[]),
"ar":L("ديك رومي قليل الصوديوم","المعلومات الغذائية للديك الرومي قليل الصوديوم","1","3 أونصة",["3 أونصة ديك رومي قليل الصوديوم"],[])}))
R.append((6942761,{
"es":L("Arroz integral sencillo con cebollín","Realce el arroz integral con una mezcla sabrosa de salsa de soya y vinagre de arroz, además de cebollín (u otras hierbas) para darle un toque de color y frescura.",
"6","1/2 taza",
["5 tallos de cebollín (en rodajas finas)","1/4 cucharadita de jengibre molido","1 cucharada de vinagre de arroz","1 cucharada de aceite de oliva","2 cucharadas de salsa de soya baja en sodio","2 tazas de caldo de verduras bajo en sodio o agua","1 taza de arroz integral"],
["En un tazón pequeño, bata la salsa de soya, el aceite de oliva, el vinagre de arroz y el jengibre. Rocíe la mezcla de salsa de soya sobre el arroz y revuelva para cubrirlo de manera uniforme. Agregue el cebollín y revuelva para incorporarlo.","En una olla a fuego alto, lleve el arroz y el caldo a ebullición. Reduzca el fuego a medio-bajo y cocine a fuego lento hasta que el arroz esté tierno, unos 40 minutos. (También puede usar una arrocera para cocinar el arroz). Esponje el arroz con un tenedor y colóquelo en un tazón grande."]),
"ar":L("أرز بني بسيط مع البصل الأخضر",
"عزّز نكهة الأرز البني بمزيج لذيذ من صلصة الصويا وخل الأرز، مع البصل الأخضر (أو أعشاب أخرى) لإضافة لمسة لون ونكهة طازجة.",
"6","½ كوب",
["5 سيقان بصل أخضر (مقطعة شرائح رفيعة)","¼ ملعقة صغيرة زنجبيل مطحون","1 ملعقة كبيرة خل الأرز","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة صلصة صويا قليلة الصوديوم","2 كوب مرق خضار قليل الصوديوم أو ماء","1 كوب أرز بني"],
["في وعاء صغير، اخفق صلصة الصويا وزيت الزيتون وخل الأرز والزنجبيل. اسكب مزيج صلصة الصويا فوق الأرز وقلّب ليتغطى بالتساوي. أضف البصل الأخضر وقلّب ليتوزع.","في قدر على نار عالية، أحضر الأرز والمرق إلى الغليان. خفّض النار إلى متوسطة منخفضة واتركه يغلي بهدوء حتى يلين الأرز، نحو 40 دقيقة. (يمكنك بدلًا من ذلك استخدام جهاز طهي الأرز). فكّ حبات الأرز بالشوكة وضعه في وعاء كبير."])}))
R.append((6942919,{
"ar":L("غراتان القرع الجوزي",
"هذا الطبق الجانبي الغني كريمي للغاية ومشبع بالجبن، ومع ذلك فإن الحصة الواحدة منه أقل من 100 سعرة حرارية.",
"8","⅛ من الطبق (مستطيل 3¼ × 4½ بوصة)",
["2 رطل قرع جوزي","1 كوب ماء","1 بخة بخاخ طهي غير لاصق","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة دقيق متعدد الاستخدامات","2 كوب نصف كريمة ونصف حليب (خالٍ من الدسم)","½ كوب جبن بارميزان (مبشور، مقسم)","½ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة زعتر طازج (مفروم)"],
["سخّن الفرن مسبقًا على 375 درجة فهرنهايت (190 درجة مئوية). اقطع القرع إلى نصفين بالطول وضعه بوجهه إلى الأسفل في طبق خبز مقاس 9×13 بوصة. اسكب الماء فوق القرع واخبزه 45 دقيقة.","أخرج القرع من الصينية وصفِّ الماء. ادهن طبق الخبز ببخاخ الطهي.","أزل البذور واغرف لب القرع من القشرة. أعد لب القرع إلى طبق الخبز المجهز، مع تفتيته إلى قطع متساوية الحجم.","ضع الزيت في مقلاة على نار متوسطة. أضف الدقيق وحرّك للمزج. اطهِ خليط الزيت والدقيق لمدة دقيقتين ثم أضف نصف الكريمة ونصف الحليب الخالي من الدسم مع الخفق. أحضره إلى الغليان مع الخفق المتكرر.","أضف ¼ كوب من جبن البارميزان والفلفل الأسود المطحون والزعتر وحرّك. استمر في التحريك حتى يذوب الجبن.","اسكب الصلصة فوق القرع الجوزي ورشّ الجبن المتبقي (¼ كوب) على السطح. اخبز 25 دقيقة أو حتى يصبح لونه ذهبيًا ويفور."])}))
R.append((6944046,{
"es":L("Puré de habas del sur de Italia (Maccu)",
"El maccu es un plato popular en Calabria, Italia, la tierra ancestral de Amy Riolo. La palabra Calabria deriva de un término bizantino que significa «tierra fértil». Esta región hace honor a su nombre con ricas tradiciones agrícolas que continúan hasta hoy. La palabra maccu proviene de la voz dialectal que significa «machacado» y se refiere a un puré hecho de habas, uno de los cultivos agrícolas más antiguos del mundo. En Calabria se sirven platos de habas frescas y secas para el Día de San José. Sirva este aperitivo solo, rociado con aceite de oliva como guarnición, o con galletas saladas, pan plano o Aros de galleta integral con pimienta negra y semillas de hinojo. Si es posible, use aceite de oliva de primera presión en frío y pecorino crotonese, un queso añejo de leche de oveja de alta calidad de Calabria. Este plato, como muchos aperitivos italianos populares, se puede servir caliente o a temperatura ambiente. Se pueden sustituir las habas por garbanzos o frijoles cannellini.",
"6","1/3 taza",
["2/3 taza de habas secas peladas, remojadas en agua hirviendo durante 1 hora y escurridas","1 cebolla pequeña (en cuartos)","1 hoja de laurel","1/4 taza de queso Pecorino Romano","2 cucharadas de aceite de oliva extra virgen (dividido)","1 cucharadita de semillas de hinojo (más un poco para decorar)","1/8 cucharadita de hojuelas de chile rojo trituradas","1/8 cucharadita de sal marina sin refinar","1/4 cucharadita de pimienta negra recién molida"],
["Coloque las habas, la cebolla y la hoja de laurel en una olla grande. Cubra con agua y lleve a ebullición a fuego alto. Reduzca el fuego a medio-bajo, tape y cocine hasta que estén tiernas, aproximadamente 1 hora.","Escurra las habas y colóquelas en un procesador de alimentos con el queso, 1 cucharada de aceite de oliva y las semillas de hinojo. Haga un puré hasta que quede suave. Pruebe y sazone con las hojuelas de chile rojo trituradas, la sal y la pimienta.","Con una cuchara, pase el puré a una fuente para servir y alise la superficie con una espátula. Rocíe con la 1 cucharada restante de aceite de oliva y espolvoree las hojuelas de chile rojo trituradas y las semillas de hinojo por encima, si lo desea."]),
"ar":L("هريس الفول الإيطالي الجنوبي (ماكّو)",
"الماكّو طبق شائع في كالابريا بإيطاليا، موطن أجداد إيمي ريولو. تُشتق كلمة كالابريا من مصطلح بيزنطي يعني «الأرض الخصبة». وتستحق هذه المنطقة اسمها بتقاليدها الزراعية الغنية التي لا تزال مستمرة حتى اليوم. وكلمة ماكّو مأخوذة من الكلمة العامية التي تعني «المهروس»، وتشير إلى هريس يُصنع من الفول، أحد أقدم المحاصيل الزراعية في العالم. تُقدَّم أطباق الفول الطازج والمجفف في كالابريا في يوم القديس يوسف. قدّم هذه المقبلات وحدها مرشوشة بزيت الزيتون كطبق جانبي، أو مع البسكويت المملح أو الخبز المسطح أو حلقات البسكويت من القمح الكامل مع الفلفل الأسود وبذور الشمر. استخدم زيت زيتون من العصرة الأولى على البارد، وجبن بيكورينو كروتونيزي، وهو جبن معتق عالي الجودة من حليب الأغنام من كالابريا، إن أمكن. يمكن تقديم هذا الطبق، مثل كثير من المقبلات الإيطالية الشهيرة، ساخنًا أو بدرجة حرارة الغرفة. ويمكن استبدال الفول بالحمص أو الفاصوليا الكانيليني.",
"6","⅓ كوب",
["⅔ كوب فول مجفف مقشر، منقوع في ماء مغلي لمدة ساعة واحدة ومصفى","1 بصلة صغيرة (مقطعة أرباعًا)","1 ورقة غار","¼ كوب جبن بيكورينو رومانو","2 ملعقة كبيرة زيت زيتون بكر ممتاز (مقسمة)","1 ملعقة صغيرة بذور الشمر (إضافة إلى كمية للتزيين)","⅛ ملعقة صغيرة رقائق الفلفل الأحمر الحار المجروشة","⅛ ملعقة صغيرة ملح بحري غير مكرر","¼ ملعقة صغيرة فلفل أسود مطحون طازجًا"],
["ضع الفول والبصل وورقة الغار في قدر كبير. غطِّها بالماء وأحضرها إلى الغليان على نار عالية. خفّض النار إلى متوسطة منخفضة وغطِّ القدر واطهِ حتى يلين الفول، نحو ساعة واحدة.","صفِّ الفول وضعه في محضّر الطعام مع الجبن و1 ملعقة كبيرة زيت زيتون وبذور الشمر. اهرسه حتى يصبح ناعمًا. تذوّق وتبّل برقائق الفلفل الأحمر المجروشة والملح والفلفل.","اغرف الهريس إلى طبق تقديم وسوِّ سطحه بالملعقة العريضة (السباتولا). رشّ عليه ملعقة كبيرة واحدة المتبقية من زيت الزيتون، وانثر فوقه رقائق الفلفل الأحمر المجروشة وبذور الشمر إن رغبت."])}))
R.append((6944484,{
"ar":L("قرع السباغيتي مع صلصة المارينارا الخفيفة",
"قرع السباغيتي سهل الطهي وبديل رائع منخفض الكربوهيدرات عن المعكرونة. وهو مثالي ليوم شتوي حين يكون الأطفال في إجازة الشتاء المدرسية.",
"6","⅙ من الوصفة",
["2 رطل قرع سباغيتي متوسط (مغسول)","2 ملعقة كبيرة زيت زيتون بكر ممتاز (مقسمة)","14 حبة طماطم روما متوسطة (مفرومة)","2 فص ثوم (مفروم)","1 حبة كراث أخضر (شالوت) متوسطة (مفرومة ناعمًا)","¼ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة ملح بحري (ناعم)","1 كوب ريحان طازج","3 ملعقة كبيرة جبن بارميجيانو ريجيانو (مبشور ناعمًا، مقسم)"],
["اثقب قرع السباغيتي بالشوكة في عدة أماكن وضعه في الميكروويف على درجة حرارة عالية حتى تلين القشرة، نحو 10-15 دقيقة. اتركه ليبرد.","بينما ينضج القرع، اخلط مكونات المارينارا (1 ملعقة كبيرة زيت زيتون والطماطم والثوم والشالوت والفلفل الأسود والملح) في وعاء متوسط الحجم.","مزّق أوراق الريحان بيدك وأضفها إلى خليط الطماطم.","اقطع القرع إلى نصفين وحضّر «السباغيتي». استخدم الشوكة لسحب الخيوط المنفردة من «السباغيتي». قلّب قرع السباغيتي مع 1 ملعقة كبيرة زيت زيتون و1 ملعقة كبيرة جبن بارميجيانو ريجيانو.","ضع القرع في طبق فطيرة. غطِّه بالمارينارا الخفيفة ورشة من جبن بارميجيانو ريجيانو المتبقي (اختياري).","قدّمه فوق قرع السباغيتي المطبوخ."])}))
R.append((6945433,{
"es":L("Magdalenas de calabaza y arándanos rojos",
"Las magdalenas de calabaza y arándanos rojos son una excelente manera de disfrutar los sabores del otoño. La calabaza ligeramente dulce y los arándanos rojos ácidos combinan a la perfección en esta receta de magdalenas apta para personas con diabetes.",
"8","1 magdalena",
["1 taza de harina de almendra","1/4 taza de harina de coco","1 cucharadita de polvo de hornear","1/2 cucharadita de canela molida","1/4 cucharadita de nuez moscada molida","1/4 cucharadita de jengibre molido","1/2 cucharadita de sal","1/2 taza de puré de calabaza (enlatado)","1/4 taza de leche de almendra sin azúcar","2 huevos grandes","1/2 taza de compota de manzana sin azúcar","2 cucharadas de mantequilla de almendra","1/4 taza de sustituto de azúcar","1/2 taza de arándanos rojos (frescos o congelados)"],
["Precaliente el horno a 350 grados F. Forre un molde para magdalenas con capacillos de papel.","En un tazón grande, bata la harina de almendra, la harina de coco, el polvo de hornear, la canela, la nuez moscada, el jengibre y la sal.","En otro tazón, bata el puré de calabaza, la leche de almendra, los huevos, la compota de manzana, la mantequilla de almendra y el sustituto de azúcar hasta que estén bien combinados.","Vierta los ingredientes húmedos sobre los ingredientes secos y revuelva solo hasta que se integren.","Incorpore suavemente los arándanos rojos.","Con una cuchara, distribuya la masa de manera uniforme en los moldecitos, llenando cada uno aproximadamente 2/3 de su capacidad.","Hornee en el horno precalentado de 18 a 20 minutos, o hasta que un palillo insertado en el centro salga limpio.","Deje enfriar las magdalenas en el molde durante 5 minutos y luego pase a una rejilla para que se enfríen por completo."]),
"ar":L("كعك المافن بالقرع اليقطيني والتوت البري",
"كعك المافن بالقرع اليقطيني والتوت البري طريقة رائعة للاستمتاع بنكهات الخريف. يتناغم القرع اليقطيني الحلو قليلًا مع التوت البري الحامض تناغمًا مثاليًا في وصفة المافن هذه المناسبة لمرضى السكري.",
"8","1 كعكة مافن",
["1 كوب دقيق اللوز","¼ كوب دقيق جوز الهند","1 ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة قرفة مطحونة","¼ ملعقة صغيرة جوزة الطيب المطحونة","¼ ملعقة صغيرة زنجبيل مطحون","½ ملعقة صغيرة ملح","½ كوب هريس القرع اليقطيني (معلب)","¼ كوب حليب اللوز غير المحلى","2 بيضة كبيرة","½ كوب هريس التفاح غير المحلى","2 ملعقة كبيرة زبدة اللوز","¼ كوب بديل السكر","½ كوب توت بري (طازج أو مجمد)"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية). بطّن قالب المافن بكؤوس ورقية.","في وعاء كبير، اخفق دقيق اللوز ودقيق جوز الهند والبيكنج باودر والقرفة وجوزة الطيب والزنجبيل والملح.","في وعاء آخر، اخفق هريس القرع اليقطيني وحليب اللوز والبيض وهريس التفاح وزبدة اللوز وبديل السكر حتى يتجانس الخليط جيدًا.","اسكب المكونات السائلة فوق المكونات الجافة وحرّك حتى تمتزج فقط.","أضف التوت البري برفق بالطي.","وزّع العجين بالملعقة بالتساوي في كؤوس المافن، واملأ كل كأس حتى ⅔ تقريبًا.","اخبز في الفرن المسخّن مسبقًا من 18 إلى 20 دقيقة أو حتى يخرج عود الأسنان نظيفًا عند غرزه في الوسط.","اترك المافن ليبرد في القالب لمدة 5 دقائق، ثم انقله إلى رف شبكي ليبرد تمامًا."])}))
R.append((6946112,{
"es":L("Salmón y espárragos en una sola bandeja",
"Esta es la cena perfecta para entre semana: está lista en menos de 30 minutos y se cocina en una sola bandeja para hornear, lo que facilita la limpieza. El salmón es rico en ácidos grasos omega-3, beneficiosos para el corazón; esta receta es una excelente manera de incluir más pescado en su plan de comidas. ¡Disfrute esta comida a principios de la primavera, cuando los espárragos están de temporada!",
"4","1 filete de salmón + 4 espárragos + 2 cucharadas de cebolla",
["1 rociada, 0.25 gramos de aceite en aerosol antiadherente","1 cebolla mediana (en rodajas finas)","4 (4 onzas) filetes de salmón sin piel","1 libra de espárragos (sin los extremos duros)","1/4 taza de mostaza Dijon en grano","1 cucharada de aceite de oliva","1/2 cucharadita de pimienta negra","1 cucharada de miel"],
["Precaliente el horno a 400°F.","Rocíe una bandeja para hornear con aceite en aerosol. Coloque la cebolla en rodajas en el centro de la bandeja. Coloque los filetes de salmón sobre las rodajas de cebolla y los espárragos alrededor del salmón.","En un tazón pequeño, bata la mostaza, el aceite de oliva, la miel y la pimienta. Unte la mezcla de mostaza sobre los filetes de salmón y rocíe el resto sobre los espárragos.","Hornee 20 minutos. Sirva cada filete de salmón con los espárragos a un lado y la cebolla sobre el salmón."]),
"ar":L("سلمون وهليون على صينية واحدة",
"إليك عشاءً مثاليًا لأيام الأسبوع، يُحضَّر في أقل من 30 دقيقة ويُطهى على صينية واحدة لتسهيل التنظيف. السلمون غني بأحماض أوميغا 3 الدهنية المفيدة للقلب؛ وهذه الوصفة طريقة رائعة لإضافة المزيد من السمك إلى خطتك الغذائية. استمتع بهذه الوجبة في أوائل الربيع حين يكون الهليون في موسمه!",
"4","1 شريحة سلمون + 4 سيقان هليون + 2 ملعقة كبيرة بصل",
["1 بخة، 0.25 غرام بخاخ طهي غير لاصق","1 بصلة متوسطة (مقطعة شرائح رفيعة)","4 (4 أونصات) شرائح سلمون منزوعة الجلد","1 رطل هليون (مقطوعة الأطراف)","¼ كوب خردل ديجون خشن","1 ملعقة كبيرة زيت زيتون","½ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة عسل"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية).","رشّ صينية خبز ببخاخ الطهي. ضع البصل المقطع في وسط الصينية. ضع شرائح السلمون فوق شرائح البصل، وضع الهليون حول السلمون.","في وعاء صغير، اخفق الخردل وزيت الزيتون والعسل والفلفل. افرد خليط الخردل فوق شرائح السلمون واسكب أي كمية زائدة على الهليون.","اخبز 20 دقيقة. قدّم كل شريحة سلمون مع الهليون بجانبها والبصل فوق السلمون."])}))
R.append((6946528,{
"ar":L("طاجن البطاطس بالجبن",
"طاجن البطاطس بالجبن طبق مفضل في الأعياد لدى كثير من العائلات. لكن هذا الطبق عادةً مليء بالسعرات الحرارية والدهون والكربوهيدرات. هذه النسخة الأكثر صحة من طاجن البطاطس ستوفر عليك مئات السعرات الحرارية وعدة غرامات من الدهون.",
"16","½ كوب",
["1 بخة، 0.25 غرام بخاخ طهي غير لاصق","2 رطل هاش براون مجمد","1 ملعقة صغيرة سمن نباتي (مارجرين)","½ كوب بصل (مفروم)","½ ملعقة صغيرة فلفل أسود","1 علبة (10.5 أونصة) حساء كريمة الدجاج المركز (قليل الدسم)","1 كوب قشدة حامضة (خالية من الدسم)","1¼ كوب جبن شيدر (قليل الدسم، مبشور)","1 كوب حليب خالٍ من الدسم"],
["سخّن الفرن مسبقًا على 375 درجة فهرنهايت (190 درجة مئوية).","رشّ صينية مقاس 13 × 9 بوصة ببخاخ الطهي. افرد الهاش براون في قاع الصينية.","في مقلاة كبيرة غير لاصقة، ذوّب السمن النباتي على نار متوسطة إلى عالية. أضف البصل وقلّبه حتى يصبح شفافًا. أضف بقية المكونات واخلطها جيدًا. اطهِ نحو 5 دقائق مع التحريك من حين لآخر.","اسكب خليط الحساء فوق الهاش براون. اخبز من 50 إلى 60 دقيقة."])}))
save("out_c25_part1.json",R)
